import {configured,signIn,signOut,hasSession,getUser,rpc,rest,upsert,insert,update,remove,uploadImage,esc,brl,dateBR,localISO} from './api.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
let state={services:[],clients:[],appointments:[],income:[],expenses:[],settings:null,hours:[],blocks:[],testimonials:[],view:'day',tab:'dashboard'};
const titles={dashboard:'Visão geral',agenda:'Agenda',financeiro:'Financeiro',clientes:'Clientes',servicos:'Serviços',configuracoes:'Configurações'};
const statusNames={pendente:'Pendente',confirmado:'Confirmado',em_andamento:'Em andamento',concluido:'Concluído',cancelado:'Cancelado'};
const cityDate=v=>new Date(v).toLocaleDateString('sv-SE',{timeZone:'America/Fortaleza'});
const cityTime=v=>new Date(v).toLocaleTimeString('pt-BR',{timeZone:'America/Fortaleza',hour:'2-digit',minute:'2-digit'});
function notify(msg,error=false){const el=$('#admin-message');el.innerHTML=`<div class="notice ${error?'error':'success'}" style="margin-bottom:20px">${esc(msg)}</div>`;setTimeout(()=>{el.innerHTML=''},7000)}
function loginMessage(msg,error=true){$('#login-message').innerHTML=`<div class="notice ${error?'error':'success'}">${esc(msg)}</div>`}
function showAdmin(){ $('#login-view').classList.add('hidden');$('#admin-view').classList.remove('hidden') }
function showLogin(){ $('#admin-view').classList.add('hidden');$('#login-view').classList.remove('hidden') }
async function loadAll(table,query){let rows=[],offset=0;for(;;){const batch=await rest(table,`${query}&limit=1000&offset=${offset}`,{auth:true});rows.push(...batch);if(batch.length<1000)return rows;offset+=1000}}
async function verifyAdmin(){await getUser();const value=await rpc('is_admin',{},true);if(value!==true)throw new Error('Esta conta não tem permissão de administrador.');showAdmin();await reload()}
if(!configured)loginMessage('Configure a URL e a chave pública do Supabase em /js/config.js antes de acessar o painel.');else if(hasSession())verifyAdmin().catch(async e=>{await signOut();showLogin();loginMessage(e.message)});
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();const btn=e.currentTarget.querySelector('button');btn.disabled=true;btn.textContent='Entrando...';try{await signIn($('#email').value.trim(),$('#password').value);await verifyAdmin()}catch(err){await signOut();loginMessage(err.message)}finally{btn.disabled=false;btn.textContent='Entrar no painel'}});
$('#logout').addEventListener('click',async()=>{await signOut();showLogin()});
$$('.admin-side nav button').forEach(b=>b.addEventListener('click',()=>setTab(b.dataset.tab)));
function setTab(tab){state.tab=tab;$$('.admin-side nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$$('.admin-tab').forEach(s=>s.classList.toggle('hidden',s.id!==`tab-${tab}`));$('#admin-title').textContent=titles[tab];render()}
async function reload(){try{const [services,clients,appointments,income,expenses,settings,hours,blocks,testimonials]=await Promise.all([
  rest('services','select=*&order=sort_order.asc',{auth:true}),
  rest('clients','select=*&order=name.asc',{auth:true}),
  loadAll('appointments','select=*,clients(name,phone,address),services(name,duration_minutes)&order=starts_at.desc'),
  loadAll('income','select=*&order=entry_date.desc'),
  loadAll('expenses','select=*&order=entry_date.desc'),
  rest('company_settings','select=*',{auth:true}),
  rest('business_hours','select=*&order=weekday.asc',{auth:true}),
  rest('blocked_slots','select=*&order=slot_date.asc',{auth:true}),
  rest('testimonials','select=*&order=created_at.desc',{auth:true})]);
  Object.assign(state,{services,clients,appointments,income,expenses,settings:settings?.[0]||null,hours,blocks,testimonials});fillSelects();render()
}catch(e){notify(`Não foi possível carregar os dados: ${e.message}`,true)}}
function fillSelects(){const opts=state.services.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('');$('#admin-booking-service').innerHTML=opts;$('#income-service').innerHTML='<option value="">Selecione</option>'+opts;$('#income-appointment').innerHTML='<option value="">Sem vínculo</option>'+state.appointments.filter(a=>a.status==='concluido'&&!state.income.some(i=>i.appointment_id===a.id)).map(a=>`<option value="${a.id}">${dateBR(cityDate(a.starts_at))} · ${esc(a.clients?.name||'Cliente')} · ${esc(a.services?.name||'Serviço')}</option>`).join('')}
function render(){if(state.tab==='dashboard')renderDashboard();if(state.tab==='agenda')renderAgenda();if(state.tab==='financeiro')renderFinance();if(state.tab==='clientes')renderClients();if(state.tab==='servicos')renderServices();if(state.tab==='configuracoes')renderSettings()}
function periodRange(kind){const today=localISO(),y=today.slice(0,4),m=today.slice(0,7);return kind==='day'?[today,today]:kind==='year'?[`${y}-01-01`,`${y}-12-31`]:[`${m}-01`,`${m}-31`]}
function inRange(v,a,b){return v>=a&&v<=b}
function renderDashboard(){const [a,b]=periodRange($('#dashboard-period').value);const incomes=state.income.filter(x=>inRange(x.entry_date,a,b)),expenses=state.expenses.filter(x=>inRange(x.entry_date,a,b)),books=state.appointments.filter(x=>inRange(cityDate(x.starts_at),a,b));const revenue=incomes.reduce((s,x)=>s+Number(x.amount),0),cost=expenses.reduce((s,x)=>s+Number(x.amount),0);$('#kpi-revenue').textContent=brl(revenue);$('#kpi-expenses').textContent=brl(cost);$('#kpi-profit').textContent=brl(revenue-cost);$('#kpi-bookings').textContent=books.length;$('#kpi-bookings-detail').textContent=`${books.filter(x=>x.status==='pendente').length} pendentes · ${books.filter(x=>x.status==='confirmado').length} confirmados`;
  const now=localISO();const upcoming=state.appointments.filter(x=>cityDate(x.starts_at)>=now&&!['cancelado','concluido'].includes(x.status)).sort((x,y)=>x.starts_at.localeCompare(y.starts_at)).slice(0,5);$('#upcoming-list').innerHTML=upcoming.length?upcoming.map(x=>`<div class="summary-row"><span>${dateBR(cityDate(x.starts_at))} · ${cityTime(x.starts_at)}<br><b>${esc(x.clients?.name||'Cliente')}</b></span><span>${esc(x.services?.name||'Serviço')}<br><span class="badge ${x.status}">${statusNames[x.status]}</span></span></div>`).join(''):'Nenhum agendamento futuro.';
  const groups={};for(const x of incomes){const k=$('#dashboard-period').value==='year'?x.entry_date.slice(0,7):x.entry_date;groups[k]??={in:0,out:0};groups[k].in+=Number(x.amount)}for(const x of expenses){const k=$('#dashboard-period').value==='year'?x.entry_date.slice(0,7):x.entry_date;groups[k]??={in:0,out:0};groups[k].out+=Number(x.amount)}const keys=Object.keys(groups).sort().slice(-10);const max=Math.max(1,...keys.flatMap(k=>[groups[k].in,groups[k].out]));$('#finance-chart').innerHTML=keys.length?keys.map(k=>`<div class="bar-group" title="${esc(k)}: entradas ${brl(groups[k].in)}, despesas ${brl(groups[k].out)}"><div class="bar" style="height:${Math.max(1,groups[k].in/max*100)}%"></div><div class="bar expense" style="height:${Math.max(1,groups[k].out/max*100)}%"></div><label>${esc(k.slice(-5))}</label></div>`).join(''):'<div class="empty">Sem lançamentos no período.</div>'}
$('#dashboard-period').addEventListener('change',renderDashboard);
function agendaRange(){const date=$('#agenda-date').value||localISO();const d=new Date(`${date}T12:00:00`);if(state.view==='day')return[date,date];if(state.view==='week'){const day=d.getDay();d.setDate(d.getDate()-day);const start=localISO(d);d.setDate(d.getDate()+6);return[start,localISO(d)]}return[`${date.slice(0,7)}-01`,`${date.slice(0,7)}-31`]}
function renderAgenda(){const[a,b]=agendaRange();const rows=state.appointments.filter(x=>inRange(cityDate(x.starts_at),a,b)).sort((x,y)=>x.starts_at.localeCompare(y.starts_at));$('#appointments-empty').classList.toggle('hidden',rows.length>0);$('#appointments-body').innerHTML=rows.map(x=>`<tr><td><b>${dateBR(cityDate(x.starts_at))}</b><br>${cityTime(x.starts_at)}</td><td><b>${esc(x.clients?.name||'—')}</b><br><a href="https://wa.me/55${esc(x.clients?.phone||'')}" target="_blank" rel="noopener">${esc(x.clients?.phone||'')}</a></td><td>${esc(x.services?.name||'—')}</td><td>${x.quoted_price!=null?brl(x.quoted_price):'—'}</td><td>${esc(x.address)}</td><td><span class="badge ${x.status}">${statusNames[x.status]}</span></td><td><button data-edit-booking="${x.id}">Editar</button><br><select data-status="${x.id}" aria-label="Alterar status"><option value="">Alterar status</option>${Object.keys(statusNames).map(k=>`<option value="${k}">${statusNames[k]}</option>`).join('')}</select></td></tr>`).join('');$$('[data-edit-booking]').forEach(b=>b.addEventListener('click',()=>openBooking(b.dataset.editBooking)));$$('[data-status]').forEach(s=>s.addEventListener('change',async()=>{if(!s.value)return;try{await update('appointments',s.dataset.status,{status:s.value,updated_at:new Date().toISOString()});notify('Status atualizado.');await reload()}catch(e){notify(e.message,true)}}))}
$('#agenda-date').value=localISO();$('#agenda-date').addEventListener('change',renderAgenda);$$('.admin-tabs [data-view]').forEach(b=>b.addEventListener('click',()=>{state.view=b.dataset.view;$$('.admin-tabs [data-view]').forEach(x=>x.classList.toggle('active',x===b));renderAgenda()}));
function openBooking(id=''){const x=state.appointments.find(a=>a.id===id);$('#booking-editor').classList.remove('hidden');$('#booking-editor-title').textContent=x?'Editar agendamento':'Novo agendamento';$('#admin-booking-id').value=id;$('#admin-booking-service').value=x?.service_id||state.services[0]?.id||'';$('#admin-booking-date').value=x?cityDate(x.starts_at):localISO();$('#admin-booking-time').value=x?cityTime(x.starts_at):'09:00';$('#admin-booking-name').value=x?.clients?.name||'';$('#admin-booking-phone').value=x?.clients?.phone||'';$('#admin-booking-address').value=x?.address||'';$('#admin-booking-notes').value=x?.notes||'';$('#admin-booking-price').value=x?.quoted_price??'';$('#admin-booking-status').value=x?.status||'pendente';$('#booking-editor').scrollIntoView({behavior:'smooth'})}
$('#new-booking').addEventListener('click',()=>openBooking());$('#close-booking-editor').addEventListener('click',()=>$('#booking-editor').classList.add('hidden'));
$('#admin-booking-form').addEventListener('submit',async e=>{e.preventDefault();const id=$('#admin-booking-id').value,service=state.services.find(x=>x.id===$('#admin-booking-service').value),date=$('#admin-booking-date').value,time=$('#admin-booking-time').value,phone=$('#admin-booking-phone').value.replace(/\D/g,'');if(!service||phone.length<10||phone.length>13){notify('Confira serviço e telefone.',true);return}const start=new Date(`${date}T${time}:00-03:00`);if(!Number.isFinite(start.getTime())){notify('Data ou horário inválido.',true);return}try{const client=(await upsert('clients',{name:$('#admin-booking-name').value.trim(),phone,address:$('#admin-booking-address').value.trim(),updated_at:new Date().toISOString()},'phone'))[0];const body={client_id:client.id,service_id:service.id,starts_at:start.toISOString(),ends_at:new Date(start.getTime()+service.duration_minutes*60000).toISOString(),status:$('#admin-booking-status').value,quoted_price:$('#admin-booking-price').value===''?null:Number($('#admin-booking-price').value),address:$('#admin-booking-address').value.trim(),notes:$('#admin-booking-notes').value.trim(),updated_at:new Date().toISOString()};if(id)await update('appointments',id,body);else await insert('appointments',body);$('#booking-editor').classList.add('hidden');notify('Agendamento salvo.');await reload()}catch(err){notify(err.message,true)}});
function financeRows(){const a=$('#finance-from').value||'0000-01-01',b=$('#finance-to').value||'9999-12-31';return[...state.income.filter(x=>inRange(x.entry_date,a,b)).map(x=>({...x,type:'Entrada',description:x.client_name||state.services.find(s=>s.id===x.service_id)?.name||'Receita'})),...state.expenses.filter(x=>inRange(x.entry_date,a,b)).map(x=>({...x,type:'Saída'}))].sort((x,y)=>y.entry_date.localeCompare(x.entry_date))}
function renderFinance(){const rows=financeRows(),revenue=rows.filter(x=>x.type==='Entrada').reduce((s,x)=>s+Number(x.amount),0),cost=rows.filter(x=>x.type==='Saída').reduce((s,x)=>s+Number(x.amount),0);$('#finance-revenue').textContent=brl(revenue);$('#finance-expenses').textContent=brl(cost);$('#finance-profit').textContent=brl(revenue-cost);$('#ledger-body').innerHTML=rows.length?rows.map(x=>`<tr><td>${dateBR(x.entry_date)}</td><td>${x.type}</td><td>${esc(x.description||'—')}${x.category?`<br><small>${esc(x.category)}</small>`:''}</td><td>${esc(x.payment_method)}</td><td><b style="color:${x.type==='Entrada'?'#24744a':'#b7282d'}">${x.type==='Entrada'?'+':'−'} ${brl(x.amount)}</b></td><td><button data-delete-ledger="${x.type==='Entrada'?'income':'expenses'}:${x.id}">Excluir</button></td></tr>`).join(''):'<tr><td colspan="6" class="empty">Nenhum lançamento neste período.</td></tr>';$$('[data-delete-ledger]').forEach(b=>b.addEventListener('click',async()=>{if(!confirm('Excluir este lançamento financeiro?'))return;const [table,id]=b.dataset.deleteLedger.split(':');try{await remove(table,id);notify('Lançamento excluído.');await reload()}catch(e){notify(e.message,true)}}))}
$('#finance-from').value=`${localISO().slice(0,7)}-01`;$('#finance-to').value=localISO();$('#income-date').value=localISO();$('#expense-date').value=localISO();$('#finance-from').addEventListener('change',renderFinance);$('#finance-to').addEventListener('change',renderFinance);
$('#income-appointment').addEventListener('change',()=>{const x=state.appointments.find(a=>a.id===$('#income-appointment').value);if(x){$('#income-client').value=x.clients?.name||'';$('#income-service').value=x.service_id;$('#income-amount').value=x.quoted_price??''}});
$('#income-form').addEventListener('submit',async e=>{e.preventDefault();const appt=$('#income-appointment').value;try{await insert('income',{entry_date:$('#income-date').value,client_name:$('#income-client').value.trim()||null,service_id:$('#income-service').value||null,appointment_id:appt||null,amount:Number($('#income-amount').value),payment_method:$('#income-payment').value,notes:$('#income-notes').value.trim()||null});e.target.reset();$('#income-date').value=localISO();notify('Entrada registrada.');await reload()}catch(err){notify(err.message,true)}});
$('#expense-form').addEventListener('submit',async e=>{e.preventDefault();try{await insert('expenses',{entry_date:$('#expense-date').value,category:$('#expense-category').value,description:$('#expense-description').value.trim(),amount:Number($('#expense-amount').value),payment_method:$('#expense-payment').value,notes:$('#expense-notes').value.trim()||null});e.target.reset();$('#expense-date').value=localISO();notify('Despesa registrada.');await reload()}catch(err){notify(err.message,true)}});
$('#export-csv').addEventListener('click',()=>{const rows=financeRows(),quote=v=>`"${String(v??'').replaceAll('"','""')}"`;const csv='\ufeffData;Tipo;Descrição;Categoria;Pagamento;Valor;Observações\r\n'+rows.map(x=>[x.entry_date,x.type,x.description,x.category,x.payment_method,x.amount,x.notes].map(quote).join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`financeiro-prime-${localISO()}.csv`;a.click();URL.revokeObjectURL(url)});
$('#print-report').addEventListener('click',()=>{const rows=financeRows();const win=window.open('','_blank');if(!win){notify('Permita a abertura de janela para salvar o relatório em PDF.',true);return}const rev=rows.filter(x=>x.type==='Entrada').reduce((s,x)=>s+Number(x.amount),0),cost=rows.filter(x=>x.type==='Saída').reduce((s,x)=>s+Number(x.amount),0);win.document.write(`<html><head><title>Relatório financeiro Prime Lava Car JP</title><style>body{font:14px Arial;margin:40px;color:#222}h1{font-size:23px}table{width:100%;border-collapse:collapse;margin-top:25px}td,th{padding:8px;border-bottom:1px solid #ddd;text-align:left}</style></head><body><h1>Prime Lava Car JP · Relatório financeiro</h1><p>${esc(dateBR($('#finance-from').value))} a ${esc(dateBR($('#finance-to').value))}</p><p>Entradas: ${brl(rev)} · Despesas: ${brl(cost)} · Lucro operacional: ${brl(rev-cost)}</p><table><tr><th>Data</th><th>Tipo</th><th>Descrição</th><th>Valor</th></tr>${rows.map(x=>`<tr><td>${dateBR(x.entry_date)}</td><td>${x.type}</td><td>${esc(x.description||'—')}</td><td>${brl(x.amount)}</td></tr>`).join('')}</table></body></html>`);win.document.close();win.focus();setTimeout(()=>win.print(),300)});
function renderClients(){const q=$('#client-search').value.toLowerCase().trim();const rows=state.clients.filter(x=>!q||x.name.toLowerCase().includes(q)||x.phone.includes(q));$('#clients-body').innerHTML=rows.length?rows.map(x=>{const apps=state.appointments.filter(a=>a.client_id===x.id),ids=new Set(apps.map(a=>a.id)),paid=state.income.filter(i=>ids.has(i.appointment_id)).reduce((s,i)=>s+Number(i.amount),0);return`<tr><td><b>${esc(x.name)}</b><details><summary style="cursor:pointer;color:#b9282d;font-size:11px">Histórico</summary>${apps.sort((a,b)=>b.starts_at.localeCompare(a.starts_at)).map(a=>`<div style="padding:7px 0;border-bottom:1px solid #eee;font-size:11px">${dateBR(cityDate(a.starts_at))} · ${esc(a.services?.name||'Serviço')} · ${statusNames[a.status]} · ${a.quoted_price!=null?brl(a.quoted_price):'Sem preço'}</div>`).join('')||'Sem agendamentos.'}<button data-client-note="${x.id}">Observações</button>${x.notes?`<p>${esc(x.notes)}</p>`:''}</details></td><td><a href="https://wa.me/55${esc(x.phone)}" target="_blank" rel="noopener">${esc(x.phone)} ↗</a></td><td>${esc(x.address)}</td><td>${apps.length}<br><small>${apps.filter(a=>a.status==='concluido').length} concluídos</small></td><td>${brl(paid)}</td></tr>`}).join(''):'<tr><td colspan="5" class="empty">Nenhum cliente encontrado.</td></tr>'}$('#client-search').addEventListener('input',renderClients);$('#clients-body').addEventListener('click',async e=>{const b=e.target.closest('[data-client-note]');if(!b)return;const client=state.clients.find(x=>x.id===b.dataset.clientNote);const value=prompt('Observações sobre o cliente:',client?.notes||'');if(value===null)return;try{await update('clients',client.id,{notes:value.slice(0,1000),updated_at:new Date().toISOString()});notify('Observações salvas.');await reload()}catch(err){notify(err.message,true)}});
function renderServices(){$('#services-body').innerHTML=state.services.map(x=>`<tr><td><b>${esc(x.name)}</b><br><small>${esc(x.description)}</small></td><td>${x.duration_minutes} min</td><td>${x.price!=null?brl(x.price):'Sob consulta'}</td><td>${x.active?'Sim':'Não'}</td><td><button data-edit-service="${x.id}">Editar</button></td></tr>`).join('');$$('[data-edit-service]').forEach(b=>b.addEventListener('click',()=>openService(b.dataset.editService)))}
function openService(id=''){const x=state.services.find(s=>s.id===id);$('#service-editor').classList.remove('hidden');$('#service-id').value=id;$('#service-name').value=x?.name||'';$('#service-slug').value=x?.slug||'';$('#service-duration').value=x?.duration_minutes||120;$('#service-price').value=x?.price??'';$('#service-image').value=x?.image_url?.startsWith('http')?x.image_url:'';$('#service-active').value=String(x?.active??true);$('#service-description-edit').value=x?.description||'';$('#service-benefits').value=x?.benefits?.join(', ')||'';$('#service-editor').scrollIntoView({behavior:'smooth'})}
$('#new-service').addEventListener('click',()=>openService());$('#close-service-editor').addEventListener('click',()=>$('#service-editor').classList.add('hidden'));
$('#service-form').addEventListener('submit',async e=>{e.preventDefault();const id=$('#service-id').value,old=state.services.find(s=>s.id===id);try{const file=$('#service-image-file').files[0];const uploaded=file?await uploadImage(file):null;const body={name:$('#service-name').value.trim(),slug:$('#service-slug').value.trim(),duration_minutes:Number($('#service-duration').value),price:$('#service-price').value===''?null:Number($('#service-price').value),image_url:uploaded||$('#service-image').value||old?.image_url||null,active:$('#service-active').value==='true',description:$('#service-description-edit').value.trim(),benefits:$('#service-benefits').value.split(',').map(s=>s.trim()).filter(Boolean),sort_order:old?.sort_order??state.services.length+1,updated_at:new Date().toISOString()};if(id)await update('services',id,body);else await insert('services',body);$('#service-editor').classList.add('hidden');notify('Serviço salvo.');await reload()}catch(err){notify(err.message,true)}});
function renderSettings(){const s=state.settings||{};$('#setting-name').value=s.name||'';$('#setting-whatsapp').value=s.whatsapp||'';$('#setting-address').value=s.address||'';$('#setting-instagram').value=s.instagram||'';$('#setting-review').value=s.review_url||'';$('#setting-about').value=s.about||'';$('#setting-logo').value=s.logo_url||'';const names=['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'];$('#hours-list').innerHTML=state.hours.map(h=>`<div class="summary-row"><span>${names[h.weekday]}</span><b>${h.is_open?`${h.start_time.slice(0,5)}–${h.end_time.slice(0,5)}`:'Fechado'}</b></div>`).join('');$('#blocks-list').innerHTML=state.blocks.map(b=>`<div class="summary-row"><span>${dateBR(b.slot_date)} · ${b.start_time?`${b.start_time.slice(0,5)}–${b.end_time.slice(0,5)}`:'Dia todo'}<br><small>${esc(b.reason||'')}</small></span><button data-delete-block="${b.id}" style="border:0;background:none;color:#b9282d">Remover</button></div>`).join('');$$('[data-delete-block]').forEach(b=>b.addEventListener('click',async()=>{try{await remove('blocked_slots',b.dataset.deleteBlock);notify('Bloqueio removido.');await reload()}catch(e){notify(e.message,true)}}));renderTestimonials()}
$('#settings-form').addEventListener('submit',async e=>{e.preventDefault();try{await upsert('company_settings',{id:true,name:$('#setting-name').value.trim(),whatsapp:$('#setting-whatsapp').value.replace(/\D/g,''),address:$('#setting-address').value.trim(),instagram:$('#setting-instagram').value||null,review_url:$('#setting-review').value||null,about:$('#setting-about').value.trim()||null,logo_url:$('#setting-logo').value||null,updated_at:new Date().toISOString()},'id');notify('Informações salvas.');await reload()}catch(err){notify(err.message,true)}});
$('#hours-day').addEventListener('change',()=>{const h=state.hours.find(x=>x.weekday===Number($('#hours-day').value));if(h){$('#hours-start').value=h.start_time.slice(0,5);$('#hours-end').value=h.end_time.slice(0,5);$('#hours-open').value=String(h.is_open)}});
$('#hours-form').addEventListener('submit',async e=>{e.preventDefault();try{await upsert('business_hours',{weekday:Number($('#hours-day').value),is_open:$('#hours-open').value==='true',start_time:$('#hours-start').value,end_time:$('#hours-end').value},'weekday');notify('Horário atualizado.');await reload()}catch(err){notify(err.message,true)}});
$('#block-form').addEventListener('submit',async e=>{e.preventDefault();const start=$('#block-start').value,end=$('#block-end').value;if(Boolean(start)!==Boolean(end)){notify('Informe início e fim, ou deixe ambos vazios para bloquear o dia todo.',true);return}try{await insert('blocked_slots',{slot_date:$('#block-date').value,start_time:start||null,end_time:end||null,reason:$('#block-reason').value.trim()||null});e.target.reset();notify('Bloqueio criado.');await reload()}catch(err){notify(err.message,true)}});
function renderTestimonials(){const box=$('#testimonials-list');box.innerHTML=state.testimonials.length?state.testimonials.map(t=>`<div class="summary-row"><span><b>${esc(t.customer_name)}</b><br>${esc(t.quote)}</span><button data-delete-testimonial="${t.id}" style="border:0;background:none;color:#b9282d">Excluir</button></div>`).join(''):'<div class="empty">Nenhuma avaliação cadastrada.</div>';$$('[data-delete-testimonial]').forEach(b=>b.addEventListener('click',async()=>{if(!confirm('Excluir esta avaliação?'))return;try{await remove('testimonials',b.dataset.deleteTestimonial);notify('Avaliação excluída.');await reload()}catch(e){notify(e.message,true)}}))}
$('#testimonial-form').addEventListener('submit',async e=>{e.preventDefault();try{await insert('testimonials',{customer_name:$('#testimonial-name').value.trim(),quote:$('#testimonial-quote').value.trim(),source_url:$('#testimonial-url').value||null,published:true});e.target.reset();notify('Avaliação publicada.');await reload()}catch(err){notify(err.message,true)}});
